use crate::validation;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct URL {
    scheme: String,
    host: String,
    port: String,
    path: String,
}

impl URL {
    pub fn new(input: &str) -> Self {
        if let Some(scheme_end) = input.find("://") {
            let scheme = &input[..scheme_end];
            let remainder = &input[scheme_end + 3..];
            let authority_end = remainder
                .find(|ch| matches!(ch, '/' | '?' | '#'))
                .unwrap_or(remainder.len());
            let authority = &remainder[..authority_end];
            let path = strip_query_and_fragment(&remainder[authority_end..]);
            let host_port = authority.rsplit_once('@').map_or(authority, |(_, tail)| tail);

            let (host, port) = if let Some(port_start) = host_port.find(':') {
                (&host_port[..port_start], &host_port[port_start + 1..])
            } else {
                (host_port, "")
            };

            Self {
                scheme: scheme.to_string(),
                host: host.to_string(),
                port: port.to_string(),
                path: path.to_string(),
            }
        } else {
            Self {
                scheme: String::new(),
                host: String::new(),
                port: String::new(),
                path: strip_query_and_fragment(input).to_string(),
            }
        }
    }

    pub fn is_valid_url(input: &str) -> bool {
        let parsed = Self::new(input);
        !parsed.host.is_empty() || !parsed.path.is_empty()
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> &str {
        &self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn scheme_is_valid(&self) -> bool {
        validation::is_scheme_valid(self.scheme())
    }

    pub fn host_is_valid(&self) -> bool {
        validation::is_host_valid(self.host())
    }

    pub fn port_is_valid(&self) -> bool {
        validation::is_port_valid(self.port())
    }
}

fn strip_query_and_fragment(input: &str) -> &str {
    let end = input
        .find(|ch| matches!(ch, '?' | '#'))
        .unwrap_or(input.len());
    &input[..end]
}

