mod test16lib;

use std::env;
use std::process::ExitCode;

use test16lib::{is_host_valid, is_port_valid, is_scheme_valid, split_path, URL};

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        return ExitCode::from(1);
    }

    let url = &args[1];

    print_bool(URL::is_valid_url(url));

    let parser = URL::new(url);

    print_bool(is_scheme_valid(parser.scheme()));
    print_bool(is_host_valid(parser.host()));
    print_bool(is_port_valid(parser.port()));

    let path_segments = split_path(parser.path());
    println!("{}", path_segments.len());

    for segment in path_segments {
        println!("{segment}");
    }

    ExitCode::SUCCESS
}

fn print_bool(value: bool) {
    println!("{}", if value { 1 } else { 0 });
}

